-- ============================================
-- LUMA — Thème 1 (Restaurant) : LONG x4 — Une soirée qui tourne mal (mauvais service)
-- ============================================


update scenarios set content = '{"characters": {"waiter": "le serveur", "friend": "ton ami(e)", "manager": "le manager"}, "start_node": "n1", "nodes": {"n1": {"speaker": "friend", "text": "We''ve been waiting fifteen minutes and no one''s even brought water.", "text_fr": "Ça fait quinze minutes qu''on attend et personne n''a même apporté d''eau.", "choices": [{"text": "Let''s flag someone down politely.", "text_fr": "Faisons signe à quelqu''un poliment.", "next": "n2"}, {"text": "Let''s give it a few more minutes first.", "text_fr": "Laissons encore quelques minutes d''abord.", "next": "n2b"}, {"text": "This is ridiculous, I''m going to complain now.", "text_fr": "C''est ridicule, je vais me plaindre maintenant.", "next": "n2c"}]}, "n2": {"speaker": "waiter", "text": "So sorry about the wait, we''re short-staffed tonight. What can I get you?", "text_fr": "Désolé pour l''attente, on manque de personnel ce soir. Je vous sers quoi ?", "choices": [{"text": "No worries, could we start with some water and the menu?", "text_fr": "Pas de souci, on pourrait commencer par de l''eau et le menu ?", "next": "n3"}, {"text": "It''s fine, but please try to keep us updated.", "text_fr": "C''est bon, mais essayez de nous tenir informés.", "next": "n3"}]}, "n2b": {"speaker": "friend", "text": "(Five more minutes pass with no sign of anyone.)", "text_fr": "(Cinq minutes de plus passent sans signe de qui que ce soit.)", "choices": [{"text": "Okay, that''s enough — let''s get someone''s attention.", "text_fr": "OK, ça suffit — attirons l''attention de quelqu''un.", "next": "n2"}, {"text": "Let''s just leave and go somewhere else.", "text_fr": "Partons juste et allons ailleurs.", "next": "end_left"}]}, "n2c": {"speaker": "waiter", "text": "I do apologize for the wait — we''ve had a rough night. Let me help right away.", "text_fr": "Je m''excuse pour l''attente — on a eu une soirée difficile. Je vous aide tout de suite.", "choices": [{"text": "I appreciate the honesty, let''s start fresh.", "text_fr": "J''apprécie l''honnêteté, repartons sur de bonnes bases.", "next": "n3"}]}, "n3": {"speaker": "waiter", "text": "Here''s the menu — I''ll be right back to take your order.", "text_fr": "Voici le menu — je reviens tout de suite prendre votre commande.", "choices": [{"text": "Take your time, we understand you''re busy.", "text_fr": "Prenez votre temps, on comprend que vous êtes débordés.", "next": "n4"}, {"text": "(Ten minutes pass before he returns.)", "text_fr": "(Dix minutes passent avant qu''il revienne.)", "next": "n4b"}]}, "n4": {"speaker": "waiter", "text": "Alright, what can I get started for you both?", "text_fr": "Bon, je vous prépare quoi tous les deux ?", "choices": [{"text": "I''ll have the salmon, and my friend will have the pasta.", "text_fr": "Je vais prendre le saumon, et mon ami prendra les pâtes.", "next": "n5"}]}, "n4b": {"speaker": "friend", "text": "This is taking forever. Are you okay to keep waiting?", "text_fr": "Ça prend une éternité. Ça va d''attendre encore ?", "choices": [{"text": "Let''s stay a bit longer, the food might be worth it.", "text_fr": "Restons encore un peu, le repas pourrait valoir le coup.", "next": "n4"}, {"text": "Honestly, I''m getting frustrated too.", "text_fr": "Honnêtement, je commence à être frustré aussi.", "next": "n4c"}]}, "n4c": {"speaker": "waiter", "text": "I''m so sorry for the delay — let me take your order right now personally.", "text_fr": "Je suis vraiment désolé pour le retard — laissez-moi prendre votre commande tout de suite personnellement.", "choices": [{"text": "Thank you, we appreciate you stepping in.", "text_fr": "Merci, on apprécie que vous interveniez.", "next": "n5"}]}, "n5": {"speaker": "waiter", "text": "(Twenty minutes later) Here''s your pasta! The salmon is coming shortly.", "text_fr": "(Vingt minutes plus tard) Voici vos pâtes ! Le saumon arrive bientôt.", "choices": [{"text": "Thank you, we''ll wait for the salmon to arrive together.", "text_fr": "Merci, on va attendre que le saumon arrive ensemble.", "next": "n6"}, {"text": "Actually, could my friend start eating? No need to wait.", "text_fr": "En fait, mon ami pourrait commencer à manger ? Pas besoin d''attendre.", "next": "n6b"}]}, "n6": {"speaker": "friend", "text": "(Ten more minutes pass. The pasta is getting cold.)", "text_fr": "(Dix minutes de plus passent. Les pâtes refroidissent.)", "choices": [{"text": "Let''s ask about the salmon.", "text_fr": "Demandons pour le saumon.", "next": "n7"}, {"text": "Let''s just start eating, it''s getting cold.", "text_fr": "Commençons à manger, ça refroidit.", "next": "n7b"}]}, "n6b": {"speaker": "friend", "text": "Are you sure? I don''t mind waiting a bit.", "text_fr": "T''es sûr ? Ça me dérange pas d''attendre un peu.", "choices": [{"text": "Really, go ahead, don''t let it get cold.", "text_fr": "Vraiment, vas-y, ne laisse pas ça refroidir.", "next": "n7b"}]}, "n7": {"speaker": "waiter", "text": "Oh no — I think there was a mix-up, let me check on that immediately.", "text_fr": "Oh non — je pense qu''il y a eu une erreur, je vérifie ça immédiatement.", "choices": [{"text": "Please do, this is getting frustrating.", "text_fr": "Faites ça, ça devient frustrant.", "next": "n8"}]}, "n7b": {"speaker": "friend", "text": "(You both start eating the pasta, sharing it while waiting.)", "text_fr": "(Vous commencez tous les deux à manger les pâtes, en les partageant en attendant.)", "choices": [{"text": "This is actually kind of fun, improvising like this.", "text_fr": "C''est en fait assez amusant, improviser comme ça.", "next": "n8b"}, {"text": "I''m still a bit annoyed about the delay, honestly.", "text_fr": "Je suis encore un peu agacé par le retard, honnêtement.", "next": "n8"}]}, "n8": {"speaker": "waiter", "text": "I''m really sorry — the salmon order got lost. I''ll rush it now, on the house.", "text_fr": "Je suis vraiment désolé — la commande de saumon s''est perdue. Je l''accélère maintenant, offerte par la maison.", "choices": [{"text": "Thank you, that''s a fair way to make it right.", "text_fr": "Merci, c''est une bonne façon de rattraper ça.", "next": "n9"}, {"text": "I appreciate that, but this evening hasn''t gone well.", "text_fr": "J''apprécie, mais cette soirée ne s''est pas bien passée.", "next": "n9b"}]}, "n8b": {"speaker": "waiter", "text": "(He arrives, slightly flustered.) I''m so sorry, the salmon got lost in the kitchen chaos!", "text_fr": "(Il arrive, un peu déstabilisé.) Je suis vraiment désolé, le saumon s''est perdu dans le chaos de la cuisine !", "choices": [{"text": "No worries, we''ve been managing just fine actually.", "text_fr": "Pas de souci, on s''est bien débrouillés en fait.", "next": "n9c"}]}, "n9": {"speaker": "waiter", "text": "It''ll be out in five minutes, I promise. Again, I''m truly sorry.", "text_fr": "Ça arrive dans cinq minutes, promis. Encore une fois, je suis vraiment désolé.", "choices": [{"text": "Thank you, we''ll wait patiently.", "text_fr": "Merci, on va attendre patiemment.", "next": "n10"}, {"text": "Could we also speak with the manager about tonight?", "text_fr": "On pourrait aussi parler au manager à propos de ce soir ?", "next": "n10b"}]}, "n9b": {"speaker": "waiter", "text": "I completely understand your frustration. Let me get my manager to make this right.", "text_fr": "Je comprends totalement votre frustration. Laissez-moi appeler mon manager pour arranger ça.", "choices": [{"text": "I''d appreciate that, thank you.", "text_fr": "J''apprécierais, merci.", "next": "n10b"}]}, "n9c": {"speaker": "waiter", "text": "You''ve both been incredibly patient tonight. I''ll still bring the salmon on the house.", "text_fr": "Vous avez tous les deux été incroyablement patients ce soir. Je vais quand même apporter le saumon offert.", "choices": [{"text": "That''s very kind, thank you for taking care of us.", "text_fr": "C''est très gentil, merci de prendre soin de nous.", "next": "n10"}]}, "n10": {"speaker": "waiter", "text": "(The salmon finally arrives, hot and beautifully plated.)", "text_fr": "(Le saumon arrive enfin, chaud et magnifiquement dressé.)", "choices": [{"text": "This actually looks amazing, thank you.", "text_fr": "Ça a vraiment l''air incroyable, merci.", "next": "n11"}]}, "n10b": {"speaker": "manager", "text": "I heard about tonight — I''m truly sorry. Let me take care of your bill entirely.", "text_fr": "J''ai entendu parler de ce soir — je suis vraiment désolé. Laissez-moi prendre en charge toute votre addition.", "choices": [{"text": "That''s very generous, thank you for making it right.", "text_fr": "C''est très généreux, merci d''avoir arrangé ça.", "next": "n11"}, {"text": "You don''t have to do that, but I appreciate the gesture.", "text_fr": "Vous n''êtes pas obligé, mais j''apprécie le geste.", "next": "n11"}]}, "n11": {"speaker": "friend", "text": "Despite everything, this turned into a pretty memorable night!", "text_fr": "Malgré tout, ça s''est transformé en une soirée assez mémorable !", "choices": [{"text": "Honestly, yeah — we''ll laugh about this later.", "text_fr": "Honnêtement, ouais — on rigolera de ça plus tard.", "next": "end_positive"}, {"text": "I''m just glad it got resolved in the end.", "text_fr": "Je suis juste content que ça se soit résolu à la fin.", "next": "end_resolved"}]}, "end_positive": {"speaker": "waiter", "text": "Thank you both for your patience — hope to see you again, hopefully with better service!", "text_fr": "Merci à vous deux pour votre patience — j''espère vous revoir, avec un meilleur service j''espère !", "end": true, "ending_label": "Une mauvaise soirée transformée en souvenir amusant 😄"}, "end_resolved": {"speaker": "manager", "text": "Thank you for your understanding tonight. We''ll do better next time.", "text_fr": "Merci pour votre compréhension ce soir. On fera mieux la prochaine fois.", "end": true, "ending_label": "Incident résolu avec professionnalisme 🤝"}, "end_left": {"speaker": "friend", "text": "(You both leave and find a lovely little place two blocks away instead.)", "text_fr": "(Vous partez tous les deux et trouvez un charmant petit endroit deux rues plus loin à la place.)", "end": true, "ending_label": "Vous êtes partis chercher mieux ailleurs 🚪"}}}'::jsonb, is_playable = true
where title = 'Une soirée qui tourne mal (mauvais service)'
  and theme_id = (select id from scenario_themes where position = 1 and language_id = (select id from languages where code = 'en'));
